CREATE OR REPLACE FUNCTION public.assign_bix_referrer(p_code text) RETURNS boolean LANGUAGE plpgsql SECURITY DEFINER SET search_path = public AS $$ DECLARE parent_id uuid; BEGIN IF auth.uid() IS NULL THEN RAISE EXCEPTION 'Sign in required'; END IF; SELECT user_id INTO parent_id FROM public.referral_codes WHERE code = upper(trim(p_code)); IF parent_id IS NULL OR parent_id = auth.uid() THEN RETURN false; END IF; IF EXISTS (SELECT 1 FROM public.referral_codes WHERE user_id = auth.uid() AND referred_by IS NOT NULL) THEN RETURN false; END IF; IF EXISTS (SELECT 1 FROM public.stakes WHERE user_id = auth.uid()) THEN RETURN false; END IF; INSERT INTO public.referral_codes (user_id, code, referred_by) VALUES (auth.uid(), 'BIX-' || (100000 + floor(random() * 900000))::int, parent_id) ON CONFLICT (user_id) DO UPDATE SET referred_by = EXCLUDED.referred_by WHERE public.referral_codes.referred_by IS NULL; RETURN true; END $$;
GRANT EXECUTE ON FUNCTION public.assign_bix_referrer(text) TO authenticated;
CREATE OR REPLACE FUNCTION public.bix_referral_tree() RETURNS TABLE (user_id uuid, parent_id uuid, depth integer) LANGUAGE sql STABLE SECURITY DEFINER SET search_path = public AS $$ WITH RECURSIVE tree AS (SELECT r.user_id, r.referred_by, 1 AS depth, ARRAY[r.user_id] AS path FROM public.referral_codes r WHERE r.referred_by = auth.uid() UNION ALL SELECT child.user_id, child.referred_by, t.depth + 1, t.path || child.user_id FROM public.referral_codes child JOIN tree t ON child.referred_by = t.user_id WHERE NOT child.user_id = ANY(t.path) AND t.depth < 50) SELECT tree.user_id, tree.referred_by, tree.depth FROM tree $$;
GRANT EXECUTE ON FUNCTION public.bix_referral_tree() TO authenticated;